from typing import List, Union
from functools import reduce

def mean_absolute_deviation(numbers: List[float]) -> Union[float, str]:
    if any(isinstance(x, str) for x in numbers):
        return 'Error'
    n = len(numbers)
    if n == 0:
        return '0.0'
    mean = sum(numbers) / n
    abs_diffs = list(map(lambda x: abs(x - mean), numbers))
    mad = sum(abs_diffs) / n
    return str(mad)

from typing import List, Any, Tuple

def filter_integers(values: List[Any], format: str) -> Tuple[List[int], str]:
    values = list(values) if isinstance(values, str) else values
    ints = list(map(lambda x: x if isinstance(x, int) else None, values))
    ints = list(filter(lambda x: x is not None, ints))
    non_ints = list(map(lambda x: '' if isinstance(x, int) else str(x), values))
    non_int_str = ' '.join(filter(lambda x: x != '', non_ints))
    if format == 'string':
        ints_str = ' '.join(map(str, ints))
        return (ints, non_int_str)
    else:
        return (ints, non_int_str)

def monotonic(l):
    # Helper for numeric list case
    def monotonic_list(l):
        if len(l) < 2:
            # No duplicates possible, trivially monotonic
            return True, int(sum(l))
        # Check duplicates recursively:
        # If any duplicates, return False
        if l[0] in l[1:]:
            return False
        # Check monotonic increasing or decreasing:
        # Monotonically increasing: l[i] < l[i+1]
        # Monotonically decreasing: l[i] > l[i+1]
        # Check first two elements to decide direction:
        if l[0] < l[1]:
            # Check all pairs satisfy strictly increasing:
            def inc_check(i):
                if i == len(l)-1:
                    return True
                if l[i] >= l[i+1]:
                    return False
                return inc_check(i+1)
            if not inc_check(0):
                return False
        elif l[0] > l[1]:
            # Check all pairs satisfy strictly decreasing:
            def dec_check(i):
                if i == len(l)-1:
                    return True
                if l[i] <= l[i+1]:
                    return False
                return dec_check(i+1)
            if not dec_check(0):
                return False
        else:
            # l[0] == l[1], duplicate case already handled above but keep for clarity
            return False
        return True, int(sum(l))

    # Helper for string case
    def monotonic_str(s):
        if len(s) < 2:
            # No duplicates possible, trivially monotonic
            return True, s
        if s[0] in s[1:]:
            return False
        if s[0] < s[1]:
            # strictly increasing alphabetically
            def inc_check(i):
                if i == len(s)-1:
                    return True
                if s[i] >= s[i+1]:
                    return False
                return inc_check(i+1)
            if not inc_check(0):
                return False
        elif s[0] > s[1]:
            # strictly decreasing alphabetically
            def dec_check(i):
                if i == len(s)-1:
                    return True
                if s[i] <= s[i+1]:
                    return False
                return dec_check(i+1)
            if not dec_check(0):
                return False
        else:
            # s[0] == s[1], duplicate case already handled above
            return False
        return True, s

    # Determine input type and dispatch
    if isinstance(l, str):
        return monotonic_str(l)
    elif isinstance(l, list):
        # Check list elements are all int or float (numbers)
        # If empty or single element list, treat as numeric list
        # If mixed types, behavior not specified, treat as numeric list anyway
        return monotonic_list(l)
    else:
        # For other types, no specification, return False
        return False

from collections import Counter

def search(lst):
    if not lst:
        return "-1"
    # Detect if list is of strings by checking type of first element
    first = lst[0]
    if isinstance(first, str):
        # For strings, return greatest lex string
        return max(lst)
    else:
        # For integers, find greatest integer x with freq(x) >= x
        freqs = Counter(lst)
        # Get candidates satisfying freq >= value
        candidates = [x for x in freqs if freqs[x] >= x]
        if not candidates:
            return "-1"
        return str(max(candidates))

def will_it_fly(q, w):
