    return "False"

def count_upper(s):
    vowels = {'A', 'E', 'I', 'O', 'U'}
    c0 = (len(s) > 0 and s[0] in vowels)
    c2 = (len(s) > 2 and s[2] in vowels)
    c4 = (len(s) > 4 and s[4] in vowels)
    count = c0 + c2 + c4
    return bin(count)[2:].zfill(2)

