    odd_digits = [int(d) for d in s if int(d) % 2 == 1]
    even_digits = [int(d) for d in s if int(d) % 2 == 0]

    if not odd_digits:
        # all digits even
        return "0" if isinstance(n, str) else "0" if isinstance(n, str) else "0"
    if not even_digits:
        # all digits odd
        return 0

    prod_odd = 1
    for d in odd_digits:
        prod_odd *= d
    prod_even = 1
