def sum_squares(lst):
    def ceil_num(x):
        # Manual ceiling without using ceil/round
        int_part = int(x)
        if x > 0 and x != int_part:
            return int_part + 1
        else:
            return int_part

    # map ceil_num to each element, then square, then sum without explicit loops
    # use sum() with a generator expression (allowed since no explicit loops)
    total = sum((ceil_num(x) ** 2 for x in lst))
    return str(total)

def order_by_points(nums):
    if not nums:
        return []
    def digit_sum(n):
        return sum(int(c) for c in str(abs(int(n))))
    sorted_nums = sorted(enumerate(nums), key=lambda x: digit_sum(x[1]))
    return ", ".join(str(x[1]) for x in sorted_nums)
